payload.arguments:
{"cmd": "$base = Join-Path $PWD.Path 'src\main\java\com\example\starter'
$files = @('InstructionRepository.java','SampleRepository.java','ReconciliationRepository.java')
foreach ($name in $files) {
    $f = Join-Path $base "curtailment\repo\$name"
    $c = [System.IO.File]::ReadAllText($f)
    $c = $c -replace 'ps\.setTimestamp\(', 'ps.setObject('
    [System.IO.File]::WriteAllText($f, $c, (New-Object System.Text.UTF8Encoding($false)))
}
$env:GRADLE_USER_HOME = (Join-Path $PWD.Path '.gradle\runner-user-home'); java -jar gradle/wrapper/gradle-wrapper.jar --no-daemon --console=plain classes", "yield_time_ms": 300000}

{"cmd": "$base = 'http://localhost:8080/api/v1/instructions'
Invoke-RestMethod -Uri "$base/1" | ConvertTo-Json -Compress
Invoke-RestMethod -Method Post -Uri "$base/1/confirm" -ContentType 'application/json' -Body '{"requestId":"demo-confirm-1"}' | ConvertTo-Json -Compress
foreach ($i in 0..3) {
    $tick = ([DateTimeOffset]::Parse('2027-01-01T02:00:00Z')).AddSeconds(900*$i).ToString('yyyy-MM-ddTHH:mm:ssZ')
    $body = "{`"requestId`":`"demo-sample-$i`",`"tickStart`":`"$tick`",`"avgPowerKw`":80}"
    Invoke-RestMethod -Method Post -Uri "$base/1/samples" -ContentType 'application/json' -Body $body | ConvertTo-Json -Compress
}
Invoke-RestMethod -Method Post -Uri "$base/1/reconciliations" -ContentType 'application/json' -Body '{"requestId":"demo-recon-1","windowStart":"2027-01-01T02:00:00Z"}' | ConvertTo-Json -Compress"}

